import { test, expect } from '@playwright/test';

test.describe('Export Personal Data as JSON File', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user-profile');
  });

  test('should successfully export personal data as a JSON file', async ({ page }) => {
    // Verify export button is visible and enabled
    const exportButton = page.getByRole('button', { name: /export/i });
    await expect(exportButton).toBeVisible();

    // Verify export button is enabled
    await expect(exportButton).toBeEnabled();

    // Click export button
    await exportButton.click();

    // Verify export dialog appears
    const exportDialog = page.locator('[data-testid="export-dialog"]');
    await expect(exportDialog).toBeVisible();

    // Verify export button is disabled in dialog
    const exportButtonInDialog = page.getByRole('button', { name: /export/i });
    await expect(exportButtonInDialog).not.toBeEnabled();

    // Verify export button is disabled
    const exportButtonOutsideDialog = page.getByRole('button', { name: /export/i });
    await expect(exportButtonOutsideDialog).not.toBeEnabled();

    // Verify export button is disabled due to dialog
    await expect(exportButtonInDialog).toBeDisabled();

    // Verify export button is disabled when dialog is open
    await expect(exportButtonOutsideDialog).toBeDisabled();

    // Verify export button is enabled when dialog is closed
    await exportDialog.click();
    await expect(exportButtonOutsideDialog).toBeEnabled();

    // Verify export file is downloaded
    const downloadButton = page.getByRole('button', { name: /download/i });
    await expect(downloadButton).toBeVisible();

    // Verify file name is correct
    const fileName = page.getByText(/personal-data.json/i);
    await expect(fileName).toBeVisible();

    // Verify file download dialog appears
    const downloadDialog = page.locator('[data-testid="download-dialog"]');
    await expect(downloadDialog).toBeVisible();

    // Verify download button is visible
    const downloadButtonInDialog = page.getByRole('button', { name: /download/i });
    await expect(downloadButtonInDialog).toBeVisible();

    // Verify download button is enabled
    await expect(downloadButtonInDialog).toBeEnabled();

    // Verify file is downloaded successfully
    await expect(downloadButtonInDialog).toBeEnabled();

    // Verify file exists in downloads folder
    const downloadsFolder = page.locator('[data-testid="downloads-folder"]');
    await expect(downloadsFolder).toBeVisible();

    const filePath = page.locator('[data-testid="downloaded-file-path"]');
    await expect(filePath).toContainText('personal-data.json');

    // Verify file is readable
    const fileContent = await page.evaluate(() => {
      const file = new File(downloadsFolder.evaluate(), 'personal-data.json');
      return file.text();
    });
    expect(fileContent).toBeDefined();

    // Verify file content is valid JSON
    const json = JSON.parse(fileContent);
    expect(json).toBeDefined();
  });

